/**
 * 角度模式枚举，支持角度和弧度切换
 */
public enum AngleMode {
    /**
     * 角度模式
     */
    DEG,

    /**
     * 弧度模式
     */
    RAD;

    /**
     * 切换角度模式
     */
    public AngleMode toggle() {
        return this == DEG ? RAD : DEG;
    }
