/**
 * 表达式解析器，将中缀表达式转换为后缀表达式（逆波兰表达式）
 */
public class ExpressionParser {

    private static final Map<String, Integer> OPERATORS = Map.of(
        "+", 1, "-", 1, "*", 2, "/", 2, "^", 3
    );

    private static final Map<String, Integer> FUNCTIONS = Map.of(
        "sin", 0, "cos", 0, "tan", 0,
        "sqrt", 0, "ln", 0, "log", 0,
        "x2", 0
    );

    /**
     * 将中缀表达式转换为后缀表达式
     */
    public List<String> toPostfix(String infix) {
        List<String> output = new ArrayList<>();
        Deque<String> stack = new ArrayDeque<>();
        StringBuilder numBuffer = new StringBuilder();

        for (int i = 0; i < infix.length(); i++) {
            char c = infix.charAt(i);

            if (Character.isDigit(c) || c == '.') {
                numBuffer.append(c);
            } else if (c == 'p' && i + 1 < infix.length() && infix.charAt(i + 1) == 'i') {
                if (numBuffer.length() > 0) {
                    output.add(numBuffer.toString());
                    numBuffer.setLength(0);
                }
                output.add(String.valueOf(Math.PI));
                i++;
            } else if (c == 'e' && (i == 0 || !Character.isLetter(infix.charAt(i - 1)))) {
                if (numBuffer.length() > 0) {
                    output.add(numBuffer.toString());
                    numBuffer.setLength(0);
                }
                output.add(String.valueOf(Math.E));
            } else if (Character.isLetter(c)) {
                if (numBuffer.length() > 0) {
                    output.add(numBuffer.toString());
                    numBuffer.setLength(0);
                }
                StringBuilder funcName = new StringBuilder();
                while (i < infix.length() && Character.isLetter(infix.charAt(i))) {
                    funcName.append(infix.charAt(i));
                    i++;
                }
                i--;
                String func = funcName.toString();
                if (FUNCTIONS.containsKey(func)) {
                    stack.push(func);
                }
            } else if (c == '(') {
                if (numBuffer.length() > 0) {
                    output.add(numBuffer.toString());
                    numBuffer.setLength(0);
                }
                stack.push("(");
            } else if (c == ')') {
                if (numBuffer.length() > 0) {
                    output.add(numBuffer.toString());
                    numBuffer.setLength(0);
                }
                while (!stack.isEmpty() && !"(".equals(stack.peek())) {
                    output.add(stack.pop());
                }
                if (!stack.isEmpty()) {
                    stack.pop();
                }
                if (!stack.isEmpty() && FUNCTIONS.containsKey(stack.peek())) {
                    output.add(stack.pop());
                }
            } else if (OPERATORS.containsKey(String.valueOf(c))) {
                if (numBuffer.length() > 0) {
                    output.add(numBuffer.toString());
                    numBuffer.setLength(0);
                }
                String op = String.valueOf(c);
                while (!stack.isEmpty() && !"(".equals(stack.peek())
