                    if (stack.isEmpty()) throw new IllegalArgumentException("表达式格式错误");
                    stack.push(Math.cos(toRadians(stack.pop())));
                }
                case "tan" -> {
                    if (stack.isEmpty()) throw new IllegalArgumentException("表达式格式错误");
                    stack.push(Math.tan(toRadians(stack.pop())));
                }
                case "sqrt" -> {
                    if (stack.isEmpty()) throw new IllegalArgumentException("表达式格式错误");
                    double a = stack.pop();
                    if (a < 0) throw new ArithmeticException("负数不能开平方根");
                    stack.push(Math.sqrt(a));
                }
                case "ln" -> {
                    if (stack.isEmpty()) throw new IllegalArgumentException("表达式格式错误");
                    double a = stack.pop();
                    if (a <= 0) throw new ArithmeticException("对数参数必须为正数");
                    stack.push(Math.log(a));
                }
                case "log" -> {
                    if (stack.isEmpty()) throw new IllegalArgumentException("表达式格式错误");
                    double a = stack.pop();
                    if (a <= 0) throw new ArithmeticException("对数参数必须为正数");
                    stack.push(Math.log10(a));
                }
                case "x2" -> {
                    if (stack.isEmpty()) throw new IllegalArgumentException("表达式格式错误");
                    double a = stack.pop();
                    stack.push(a * a);
                }
                default -> stack.push(Double.parseDouble(token));
            }
        }

