        return stack.pop();
    }

    private double toRadians(double angle) {
        return angleMode == AngleMode.DEG ? Math.toRadians(angle) : angle;
    }

    private double applyOperator(String op, double a, double b) {
        return switch (op) {
            case "+" -> a + b;
            case "-" -> a - b;
            case "*" -> a * b;
            case "/" -> { if (b == 0) throw new ArithmeticException("除数不能为零"); yield a / b; }
            case "^" -> Math.pow(a, b);
            default -> throw new IllegalArgumentException("未知运算符: " + op);
        };
    }

    /**
     * 格式化结果为字符串
     */
    public String formatResult(double result) {
        if (Double.isInfinite(result)) return "Error: Overflow";
        if (Double.isNaN(result)) return "Error: Invalid";
        if (result == Math.floor(result) && Math.abs(result) < Long.MAX_VALUE) {
            return String.valueOf((long) result);
        }
        String str = String.valueOf(result);
        // 限制小数位数
        if (str.length() > 15) {
            str = String.format("%.10f", result);
            str = str.replaceAll("0*$", "").replaceAll("\.$", "");
        }
        return str;
    }
}

