/**
 * 计算器状态模型，管理运行时状态
 */
public class CalculatorState {

    /** 当前输入表达式 */
    private StringBuilder expression;

    /** 当前角度模式 */
    private AngleMode angleMode;

    /** 是否刚计算出结果 */
    private boolean resultJustCalculated;

    public CalculatorState() {
        this.expression = new StringBuilder();
        this.angleMode = AngleMode.DEG;
        this.resultJustCalculated = false;
    }

    /**
     * 添加字符到表达式
     */
    public void append(char c) {
        expression.append(c);
        resultJustCalculated = false;
    }

    /**
     * 添加字符串到表达式
     */
    public void append(String s) {
        expression.append(s);
        resultJustCalculated = false;
    }

    /**
     * 删除最后一个字符
     */
    public void deleteLast() {
        if (expression.length() > 0) {
            expression.deleteCharAt(expression.length() - 1);
        }
    }

    /**
     * 清空表达式
     */
    public void clear() {
        expression.setLength(0);
        resultJustCalculated = false;
    }

    /**
     * 清空当前输入（保留表达式内容）
     */
    public void clearEntry() {
        // 清除表达式，但保留操作符
        String expr = expression.toString();
        expression.setLength(0);
        // 保留最后一个操作符之前的部分
        int lastOpIndex = -1;
        for (int i = expr.length() - 1; i >= 0; i--) {
            char c = expr.charAt(i);
            if (c == '+' || c == '-' || c == '*' || c == '/' || c == '^') {
                lastOpIndex = i;
                break;
            }
        }
        if (lastOpIndex >= 0) {
            expression.append(expr.substring(0, lastOpIndex + 1));
        }
    }

    /**
     * 获取当前表达式字符串
     */
    public String getExpression() {
        return expression.toString();
    }

    /**
     * 设置表达式
     */
    public void setExpression(String expr) {
        expression.setLength(0);
        expression.append(expr);
    }

    /**
     * 替换整个表达式
     */
    public void replaceExpression(String newExpr) {
        expression.setLength(0);
        expression.append(newExpr);
        resultJustCalculated = true;
    }

    public AngleMode getAngleMode() {
        return angleMode;
    }

    public void toggleAngleMode() {
        angleMode = angleMode.toggle();
    }

    public void setAngleMode(AngleMode mode) {
        this.angleMode = mode;
    }

    public boolean isResultJustCalculated() {
        return resultJustCalculated;
    }

    public void setResultJustCalculated(boolean resultJustCalculated) {
        this.resultJustCalculated = resultJustCalculated;
    }
}

